<?php
namespace App\Http\Controllers\Admin;
use App\Models\IkontrolInstance;use App\Services\IkontrolInstanceOperationsService;use Illuminate\Http\Request;use Illuminate\Validation\Rules\Password;use Throwable;
class InstanceOperationController{
 public function run(Request$r,IkontrolInstance$instance,string$operation,IkontrolInstanceOperationsService$s){try{$email=$operation==='health'?$r->validate(['email'=>['nullable','email','max:255']])['email']??null:null;$result=match($operation){'files'=>$s->verifyFiles($instance),'database'=>$s->verifyDatabase($instance),'reassign-user'=>$s->reassignDatabaseUser($instance),'key'=>$s->key($instance),'cache'=>$s->clearCache($instance),'migrate'=>$s->migrate($instance),'health'=>$s->health($instance,$email),default=>abort(404)};return back()->with('success','Operación completada: '.$result['status'])->with('operation_result',$result);}catch(Throwable$e){app(\App\Services\AuditService::class)->record('instance_operation_failed','Falló una operación controlada.',$instance,['operation'=>$operation,'error_type'=>class_basename($e)]);return back()->with('error',$e->getMessage());}}
 public function admin(Request$r,IkontrolInstance$instance,string$operation,IkontrolInstanceOperationsService$s){abort_unless(in_array($operation,['create','reset'],true),404);$data=$r->validate(['name'=>[$operation==='create'?'required':'nullable','string','max:150'],'email'=>['required','email','max:255'],'password'=>['required','confirmed',Password::min(12)]]);try{$result=$operation==='create'?$s->provisionAdmin($instance,$data['name'],$data['email'],$data['password']):$s->resetAdminPassword($instance,$data['email'],$data['password']);return back()->with('success','Operación administrativa completada.')->with('operation_result',$result);}catch(Throwable$e){app(\App\Services\AuditService::class)->record('instance_admin_operation_failed','Falló una operación administrativa controlada.',$instance,['operation'=>$operation,'error_type'=>class_basename($e)]);return back()->with('error',$e->getMessage());}}
 public function destructive(Request$r,IkontrolInstance$instance,string$operation,IkontrolInstanceOperationsService$s){$data=$r->validate(['confirmation'=>['required','string'],'delete_folder'=>['sometimes','boolean'],'delete_database'=>['sometimes','boolean'],'delete_record'=>['sometimes','boolean']]);try{if($operation==='restart'){$s->restart($instance,$data['confirmation']);return back()->with('success','Reinicio y reprovisioning ejecutados.');}abort_unless($operation==='delete',404);$s->delete($instance,$data['confirmation'],(bool)($data['delete_folder']??false),(bool)($data['delete_database']??false),(bool)($data['delete_record']??false));return($data['delete_record']??false)?redirect()->route('instances.index')->with('success','Instalación de prueba eliminada.'):back()->with('success','Recursos seleccionados eliminados.');}catch(Throwable$e){return back()->with('error',$e->getMessage());}}
}
